#[test]
fn directive_contract_has_no_generic_execution_field() {
    const PROTO: &str = include_str!("../proto/mindleak/ackplane/v1/node_sync.proto");
    let field_lines = PROTO
        .lines()
        .map(str::trim)
        .filter(|line| !line.starts_with("//") && line.ends_with(';') && line.contains('='));

    for field in field_lines {
        let field_name = field
            .split('=')
            .next()
            .and_then(|declaration| declaration.split_whitespace().last())
            .unwrap_or_default();
        assert!(
            !matches!(
                field_name,
                "command" | "shell" | "shell_command" | "execute"
            ),
            "the directive protocol must stay typed, found forbidden field `{field_name}`"
        );
    }
}

